/** Every method the peer may call on us, by handler key. */
export const inbound = {
  cancelRequestReceived: {
    method: "$/cancel_request",
    kind: "notification",
    params: CancelRequestReceivedRequest,
  },
  elicitationComplete: {
    method: "elicitation/complete",
    kind: "notification",
    params: ElicitationCompleteRequest,
  },
  elicitationCreate: {
    method: "elicitation/create",
    kind: "request",
    params: CreateElicitationRequest,
    result: ElicitationCreateResponse,
  },
  fsReadTextFile: {
    method: "fs/read_text_file",
    kind: "request",
    params: FsReadTextFileRequest,
    result: ReadTextFileResponse,
  },
  fsWriteTextFile: {
    method: "fs/write_text_file",
    kind: "request",
    params: FsWriteTextFileRequest,
    result: WriteTextFileResponse,
  },
  sessionRequestPermission: {
    method: "session/request_permission",
    kind: "request",
    params: SessionRequestPermissionRequest,
    result: RequestPermissionResponse,
  },
  sessionUpdates: { method: "session/update", kind: "notification", params: SessionUpdatesRequest },
  terminalCreate: {
    method: "terminal/create",
    kind: "request",
    params: TerminalCreateRequest,
    result: CreateTerminalResponse,
  },
  terminalKill: {
    method: "terminal/kill",
    kind: "request",
    params: TerminalKillRequest,
    result: KillTerminalResponse,
  },
  terminalOutput: {
    method: "terminal/output",
    kind: "request",
    params: TerminalOutputRequest,
    result: TerminalOutputResponse,
  },
  terminalRelease: {
    method: "terminal/release",
    kind: "request",
    params: TerminalReleaseRequest,
    result: ReleaseTerminalResponse,
  },
  terminalWaitForExit: {
    method: "terminal/wait_for_exit",
    kind: "request",
    params: TerminalWaitForExitRequest,
    result: WaitForTerminalExitResponse,
  },
} as const satisfies Record<string, JsonRpc.InboundMethod>;

/** Implementations for the methods the peer calls on us. Unimplemented requests are answered MethodNotFound. */
export interface InboundHandlers<R = never> {
  readonly cancelRequestReceived?: (
    params: CancelRequestReceivedRequest,
  ) => Effect.Effect<void, never, R>;
  readonly elicitationComplete?: (
    params: ElicitationCompleteRequest,
  ) => Effect.Effect<void, never, R>;
  readonly elicitationCreate?: (
    params: CreateElicitationRequest,
  ) => Effect.Effect<ElicitationCreateResponse, JsonRpc.HandlerError, R>;
  readonly fsReadTextFile?: (
    params: FsReadTextFileRequest,
  ) => Effect.Effect<ReadTextFileResponse, JsonRpc.HandlerError, R>;
  readonly fsWriteTextFile?: (
    params: FsWriteTextFileRequest,
  ) => Effect.Effect<WriteTextFileResponse, JsonRpc.HandlerError, R>;
  readonly sessionRequestPermission?: (
    params: SessionRequestPermissionRequest,
  ) => Effect.Effect<RequestPermissionResponse, JsonRpc.HandlerError, R>;
  readonly sessionUpdates?: (params: SessionUpdatesRequest) => Effect.Effect<void, never, R>;
  readonly terminalCreate?: (
    params: TerminalCreateRequest,
  ) => Effect.Effect<CreateTerminalResponse, JsonRpc.HandlerError, R>;
  readonly terminalKill?: (
    params: TerminalKillRequest,
  ) => Effect.Effect<KillTerminalResponse, JsonRpc.HandlerError, R>;
  readonly terminalOutput?: (
    params: TerminalOutputRequest,
  ) => Effect.Effect<TerminalOutputResponse, JsonRpc.HandlerError, R>;
  readonly terminalRelease?: (
    params: TerminalReleaseRequest,
  ) => Effect.Effect<ReleaseTerminalResponse, JsonRpc.HandlerError, R>;
  readonly terminalWaitForExit?: (
    params: TerminalWaitForExitRequest,
  ) => Effect.Effect<WaitForTerminalExitResponse, JsonRpc.HandlerError, R>;
}

/** Bind typed inbound handlers for a connection (`JsonRpc.connect(transport, handlers({...}))`). */
export const handlers = <R = never>(
  impl: InboundHandlers<R>,
): Effect.Effect<JsonRpc.PeerHandlers, never, R> => JsonRpc.bindHandlers<R>(inbound, impl as any);
